import { Agent } from "@voltagent/core";
import { openai } from "@ai-sdk/openai";
import { registerInstrumentations } from "@opentelemetry/instrumentation";
import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";
import { Resource } from "@opentelemetry/resources";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import { SimpleSpanProcessor } from "@opentelemetry/sdk-trace-base";
import { SemanticResourceAttributes } from "@opentelemetry/semantic-conventions";
import * as fs from "fs";
import * as path from "path";

// Configure OpenTelemetry
const resource = Resource.default().merge(
  new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: "voltagent-tracing-app",
  })
);

const provider = new NodeTracerProvider({ resource });

// Configure OTLP exporter to send traces to local collector
const exporter = new OTLPTraceExporter({
  url: "http://localhost:4318/v1/traces",
});

provider.addSpanProcessor(new SimpleSpanProcessor(exporter));

// Register the provider globally
provider.register();

// Enable AI SDK instrumentation
registerInstrumentations({
  instrumentations: [],
});

// Create the agent with telemetry enabled
const agent = new Agent({
  name: "Assistant",
  instructions: "You are a helpful assistant.",
  model: openai("gpt-4o-mini"),
  experimental_telemetry: {
    isEnabled: true,
  },
});

async function main() {
  try {
    // Send a single message "Hello" to the agent
    const result = await agent.run({ input: "Hello" });

    // Log the response to output.log
    const outputPath = path.join(__dirname, "output.log");
    fs.writeFileSync(outputPath, JSON.stringify(result, null, 2));

    // Flush the tracer to ensure all traces are exported
    await provider.forceFlush();

    // Exit the process
    process.exit(0);
  } catch (error) {
    console.error("Error:", error);
    await provider.forceFlush();
    process.exit(1);
  }
}

main();

